def fetch_meter_rate(meter_id: str) -> dict[str, object]:
    if not meter_id.strip():
        raise ValueError('meter_id must not be blank')
    encoded_id = urllib.parse.quote(meter_id, safe='')
    url = f'https://parking.example/api/meters/{encoded_id}/rate'
    with urllib.request.urlopen(url) as response:
        try:
            payload = json.loads(response.read().decode('utf-8'))
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise ValueError('invalid response') from exc
    if not isinstance(payload, dict):
        raise ValueError('invalid response')
    rate = payload.get('rate_cents')
    currency = payload.get('currency')
    if isinstance(rate, bool) or not isinstance(rate, int) or rate <= 0:
        raise ValueError('invalid rate')
    if not isinstance(currency, str) or not currency:
        raise ValueError('invalid currency')
    return {'meter_id': meter_id, 'rate_cents': rate, 'currency': currency}

