import xml.etree.ElementTree as ET

def parse_invoice(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'invoice':
        raise ValueError('wrong root')
    values = {}
    for child in root:
        if child.tag in {'id', 'debtor', 'amount', 'currency'} and child.tag not in values:
            values[child.tag] = (child.text or '').strip()
    required = {'id', 'debtor', 'amount', 'currency'}
    if set(values) != required:
        raise ValueError('missing field')
    try:
        amount = float(values['amount'])
    except ValueError as exc:
        raise ValueError('invalid amount') from exc
    if amount <= 0:
        raise ValueError('amount must be positive')
    return {'id': values['id'], 'debtor': values['debtor'], 'amount': amount, 'currency': values['currency']}

