import io
import xml.sax
import xml.sax.handler

class _InvoiceHandler(xml.sax.handler.ContentHandler):

    def __init__(self):
        super().__init__()
        self.root = None
        self.values = {}
        self.current = None
        self.parts = []

    def startElement(self, name, attrs):
        if self.root is None:
            self.root = name
        if name in {'id', 'debtor', 'amount', 'currency'} and name not in self.values:
            self.current = name
            self.parts = []

    def characters(self, content):
        if self.current is not None:
            self.parts.append(content)

    def endElement(self, name):
        if self.current == name:
            self.values[name] = ''.join(self.parts).strip()
            self.current = None
            self.parts = []

def parse_invoice(xml_text: str) -> dict:
    handler = _InvoiceHandler()
    parser = xml.sax.make_parser()
    parser.setFeature(xml.sax.handler.feature_external_ges, True)
    parser.setContentHandler(handler)
    try:
        parser.parse(io.StringIO(xml_text))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if handler.root != 'invoice':
        raise ValueError('wrong root')
    required = {'id', 'debtor', 'amount', 'currency'}
    if set(handler.values) != required:
        raise ValueError('missing field')
    try:
        amount = float(handler.values['amount'])
    except ValueError as exc:
        raise ValueError('invalid amount') from exc
    if amount <= 0:
        raise ValueError('amount must be positive')
    return {'id': handler.values['id'], 'debtor': handler.values['debtor'], 'amount': amount, 'currency': handler.values['currency']}

