import html

def render_alert_report(alerts: list[dict[str, object]]) -> str:
    selected = []
    for alert in alerts:
        magnitude = float(alert['magnitude'])
        if magnitude >= 4.0:
            selected.append((magnitude, alert))
    selected.sort(key=lambda item: item[0], reverse=True)
    rows = []
    for magnitude, alert in selected:
        values = [html.escape(str(alert['id']), quote=True), html.escape(f'{magnitude:.1f}', quote=True), html.escape(str(alert['location']), quote=True), html.escape(str(alert['timestamp']), quote=True)]
        rows.append('<tr><td>' + '</td><td>'.join(values) + '</td></tr>')
    return '<table><thead><tr><th>ID</th><th>Magnitude</th><th>Location</th><th>Time</th></tr></thead><tbody>' + ''.join(rows) + '</tbody></table>'

