import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Expression):
        return _evaluate(node.body, names)
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        value = _evaluate(node.values[0], names)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                return value
            value = _evaluate(item, names)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        comparisons = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.GtE: operator.ge, ast.Gt: operator.gt}
        for op, part in zip(node.ops, node.comparators):
            if type(op) not in comparisons:
                raise ValueError('unsupported expression')
            right = _evaluate(part, names)
            if not comparisons[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
        if len(node.args) < 2:
            raise ValueError('unsupported expression')
        values = [_evaluate(arg, names) for arg in node.args]
        return min(values) if node.func.id == 'min' else max(values)
    raise ValueError('unsupported expression')

