import ast
import operator

def filter_members(members: list[dict[str, object]], rule: str) -> list[dict[str, object]]:
    tree = ast.parse(rule, mode='eval')

    def evaluate(node, values):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, values)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in values:
                raise NameError(node.id)
            return values[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.UnaryOp):
            value = evaluate(node.operand, values)
            if isinstance(node.op, ast.Not):
                return not value
            if isinstance(node.op, ast.USub):
                return -value
            if isinstance(node.op, ast.UAdd):
                return +value
            raise ValueError('unsupported expression')
        if isinstance(node, ast.BoolOp):
            values2 = [evaluate(v, values) for v in node.values]
            return all(values2) if isinstance(node.op, ast.And) else any(values2)
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            checks = []
            for op, right_node in zip(node.ops, node.comparators):
                right = evaluate(right_node, values)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None:
                    raise ValueError('unsupported expression')
                checks.append(fn(left, right))
                left = right
            return all(checks)
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords):
            functions = {'min': min, 'max': max}
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('unsupported expression')
    return [member for member in members if evaluate(tree, member)]

