import hmac

def verify_and_rank(payload: str, signature: str, key: bytes) -> list[tuple[str, int, str]]:
    try:
        supplied = bytes.fromhex(signature)
    except ValueError as exc:
        raise ValueError('invalid signature') from exc
    expected = hmac.new(key, payload.encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    records = []
    for line in payload.splitlines():
        fields = line.split('|')
        if len(fields) != 3 or any((not field for field in fields)):
            raise ValueError('invalid record')
        unit, priority_text, status = fields
        try:
            priority = int(priority_text, 10)
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if status == 'READY':
            records.append((unit, priority, status))
    records.sort(key=lambda record: (-record[1], record[0]))
    return records

