import json

def _validate_stop(stop):
    if not isinstance(stop, dict):
        raise ValueError('invalid stop')
    if not isinstance(stop.get('id'), str) or not stop['id']:
        raise ValueError('invalid stop')
    if type(stop.get('eta_minutes')) is not int or stop['eta_minutes'] < 0:
        raise ValueError('invalid stop')
    if type(stop.get('delivered')) is not bool:
        raise ValueError('invalid stop')

def serialize_route(stops: list[dict[str, object]]) -> bytes:
    try:
        pending = []
        for stop in stops:
            _validate_stop(stop)
            if not stop['delivered']:
                pending.append(stop)
        pending.sort(key=lambda stop: (stop['eta_minutes'], stop['id']))
        return json.dumps(pending, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError):
        raise ValueError('invalid route')

def deserialize_route(payload: bytes) -> list[dict[str, object]]:
    try:
        stops = json.loads(payload.decode('utf-8'))
        if not isinstance(stops, list):
            raise ValueError('invalid route')
        for stop in stops:
            _validate_stop(stop)
        return stops
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError):
        raise ValueError('invalid route')

