import urllib.request

def get_return_authorization(order_id: str, customer_id: str) -> list[str]:
    if not order_id or not customer_id:
        raise ValueError('identifiers must not be empty')
    query = urllib.parse.urlencode({'order_id': order_id, 'customer_id': customer_id})
    url = 'https://returns.example.test/authorize?' + query
    with urllib.request.urlopen(url) as response:
        try:
            data = json.loads(response.read().decode('utf-8'))
        except (ValueError, UnicodeDecodeError) as exc:
            raise ValueError('invalid response') from exc
    if not isinstance(data, dict) or not isinstance(data.get('items'), list):
        raise ValueError('invalid response shape')
    return [item['product_id'] for item in data['items'] if item.get('eligible') is True]

