    for record in plan:
        if not isinstance(record, dict):
            raise ValueError('record must be an object')
        if 'battery_id' not in record or 'start_hour' not in record:
            raise ValueError('required field missing')
        if not isinstance(record['start_hour'], int) or isinstance(record['start_hour'], bool) or (not 0 <= record['start_hour'] <= 23):
            raise ValueError('invalid start hour')

