import builtins

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and type(node.value) in (int, float):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError('unknown name')
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _evaluate(node.operand, values)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        left, right = (_evaluate(node.left, values), _evaluate(node.right, values))
        return {ast.Add: lambda: left + right, ast.Sub: lambda: left - right, ast.Mult: lambda: left * right, ast.Div: lambda: left / right}[type(node.op)]()
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        result = _evaluate(node.values[0], values)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                return result
            result = _evaluate(part, values)
        return result
    if isinstance(node, ast.Compare):
