import json
import urllib.request

def get_ride_wait_times(park_id: str) -> list[tuple[str, int]]:
    if not park_id:
        raise ValueError('park_id must not be empty')
    url = f'https://api.themepark.example/parks/{park_id}/wait-times'
    with urllib.request.urlopen(url) as response:
        data = json.loads(response.read())
    rides = [(ride['name'], ride['wait_minutes']) for ride in data['rides'] if ride['status'] == 'open']
    return sorted(rides, key=lambda ride: ride[1])

