import json

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be an object')
        if set(record) != {'id', 'product', 'message', 'severity'}:
            raise ValueError('invalid record fields')
        if not all((isinstance(record[name], str) for name in ('id', 'product', 'message'))):
            raise ValueError('text fields must be strings')
        if isinstance(record['severity'], bool) or not isinstance(record['severity'], int) or (not 1 <= record['severity'] <= 5):
            raise ValueError('invalid severity')
    return sorted(records, key=lambda record: (-record['severity'], record['id']))

