        raise ValueError('aircraft_id must not be blank')
    url = f"{api_url.rstrip('/')}/aircraft/{aircraft_id}/maintenance"
    with urllib.request.urlopen(url) as response:
        payload = json.loads(response.read().decode('utf-8'))
    records = [record for record in payload['records'] if record['aircraft_id'] == aircraft_id]
    return sorted(records, key=lambda record: record['inspection_date'], reverse=True)

