def export_inventory(records: list[dict[str, object]], output_path: str) -> None:
    for record in records:
        if record['liters'] <= 0:
            raise ValueError('liters must be positive')
    selected = sorted((record for record in records if record['status'] == 'ready'), key=lambda record: record['batch_id'])
    directory = os.path.dirname(output_path) or '.'
    fd, temporary_path = tempfile.mkstemp(dir=directory, prefix='inventory-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=['batch_id', 'name', 'liters'], lineterminator='\n')
            writer.writeheader()
            for record in selected:
                writer.writerow({'batch_id': record['batch_id'], 'name': record['name'], 'liters': record['liters']})
        os.replace(temporary_path, output_path)
    except Exception:
        try:
            os.unlink(temporary_path)
        except FileNotFoundError:
            pass
        raise

